    int low, high, mid, pos = -1;

    if (scanf("%c", &key) != 1)
        return 1;

    low = 0;
    high = (int)(sizeof(a) - 2);
    while (low <= high) {
        mid = (low + high) / 2;
        if (a[mid] == key) {
            pos = mid;
            break;
        }
        else if (a[mid] < key) {
            low = mid + 1;
        }
        else {
            high = mid - 1;
        }
    }

    if (pos >= 0)
        printf("%d\n", pos);
    else
        printf("**\n");

    return 0;
}

