        len = len + 1;
    if (len == 0)
        return 1;

    /* 找最大元素（首次出现的位置） */
    max = a[0];
    for (i = 1; i < len; i++) {
        if (a[i] > max) {
            max = a[i];
            pos = i;
        }
    }

    /* a[0..pos] + b + a 的剩余部分 */
    k = 0;
    for (i = 0; i <= pos; i++)
        r[k++] = a[i];
    for (i = 0; b[i] != '\0'; i++)
        r[k++] = b[i];
    for (i = pos + 1; i < len; i++)
        r[k++] = a[i];
    r[k] = '\0';

    printf("%s\n", r);

    return 0;
}

